/**
 * All events that can be recorded by Maka.
 *
 * Events are divided into:
 * - business events: generated by business services
 * - behavioral events: generated from user behavior
 */

export const EventNames = {
  // ---------------------------------------------------------------------------
  // Business events
  // ---------------------------------------------------------------------------

  SESSION_CREATED: "session.created",

  STORE_CREATED: "store.created",
  STORE_UPDATED: "store.updated",
  STORE_ACTIVATED: "store.activated",
  STORE_DEACTIVATED: "store.deactivated",

  PRODUCT_CREATED: "product.created",
  PRODUCT_UPDATED: "product.updated",
  PRODUCT_ARCHIVED: "product.archived",
  PRODUCT_UNARCHIVED: "product.unarchived",
  PRODUCT_AVAILABILITY_CHANGED: "product.availability_changed",

  CART_CREATED: "cart.created",
  CART_ITEM_ADDED: "cart.item_added",
  CART_ITEM_UPDATED: "cart.item_updated",
  CART_ITEM_REMOVED: "cart.item_removed",
  CART_CLEARED: "cart.cleared",

  ORDER_CREATED: "order.created",
  ORDER_CONFIRMED: "order.confirmed",
  ORDER_PREPARING: "order.preparing",
  ORDER_READY: "order.ready",
  ORDER_DELIVERING: "order.delivering",
  ORDER_DELIVERED: "order.delivered",
  ORDER_CANCELLED: "order.cancelled",

  // ---------------------------------------------------------------------------
  // Behavioral events
  // ---------------------------------------------------------------------------

  STORE_VIEWED: "store.viewed",
  STORE_SHARED: "store.shared",

  PRODUCT_VIEWED: "product.viewed",
  PRODUCT_SHARED: "product.shared",

  CATEGORY_VIEWED: "category.viewed",

  SEARCH_PERFORMED: "search.performed",

  CART_VIEWED: "cart.viewed",

  CHECKOUT_STARTED: "checkout.started",
  CHECKOUT_SUBMITTED: "checkout.submitted",
  CHECKOUT_VALIDATION_FAILED: "checkout.validation_failed",
} as const;

export type EventName = (typeof EventNames)[keyof typeof EventNames];

/**
 * ---------------------------------------------------------------------------
 * Shared metadata
 * ---------------------------------------------------------------------------
 */

export type ShareChannel = "whatsapp" | "tiktok" | "copy_link" | "other";

/**
 * ---------------------------------------------------------------------------
 * Event-specific metadata
 * ---------------------------------------------------------------------------
 */

export interface StoreSharedMetadata {
  channel: ShareChannel;
}

export interface ProductSharedMetadata {
  channel: ShareChannel;
}

export interface SearchPerformedMetadata {
  query: string;
  results_count: number;
}

export interface ProductAvailabilityChangedMetadata {
  previous: "available" | "unavailable";
  current: "available" | "unavailable";
}

export interface CartItemAddedMetadata {
  quantity: number;
  unit_price: number;
}

export interface CartItemUpdatedMetadata {
  previous_quantity: number;
  quantity: number;
}

export interface CartItemRemovedMetadata {
  quantity: number;
}

export interface CartClearedMetadata {
  item_count?: number;
}

export interface OrderCreatedMetadata {
  source: "cart" | "product";
}

export interface CheckoutValidationFailedMetadata {
  field: "buyer_name" | "phone" | "delivery_city" | "delivery_address";

  reason: string;
}

/**
 * ---------------------------------------------------------------------------
 * Event metadata map
 * ---------------------------------------------------------------------------
 *
 * Events not listed here do not require metadata.
 */

export interface EventMetadataMap {
  "store.shared": StoreSharedMetadata;
  "product.shared": ProductSharedMetadata;
  "search.performed": SearchPerformedMetadata;
  "product.availability_changed": ProductAvailabilityChangedMetadata;
  "cart.item_added": CartItemAddedMetadata;
  "cart.item_updated": CartItemUpdatedMetadata;
  "cart.item_removed": CartItemRemovedMetadata;
  "cart.cleared": CartClearedMetadata;
  "order.created": OrderCreatedMetadata;
  "checkout.validation_failed": CheckoutValidationFailedMetadata;
}

/**
 * ---------------------------------------------------------------------------
 * Event context
 * ---------------------------------------------------------------------------
 */

export interface EventContext {
  sessionId?: string | null;
  userId?: string | null;
  storeId?: string | null;
  productId?: string | null;
  orderId?: string | null;
}

/**
 * ---------------------------------------------------------------------------
 * Event payload
 * ---------------------------------------------------------------------------
 *
 * Metadata is automatically typed according to the event name.
 */

export type EventPayload<T extends EventName> = T extends keyof EventMetadataMap
  ? EventContext & {
      name: T;
      metadata: EventMetadataMap[T];
      eventKey?: string | null;
      occurredAt?: Date;
    }
  : EventContext & {
      name: T;
      metadata?: Record<string, never>;
      eventKey?: string | null;
      occurredAt?: Date;
    };
